def main():
    claims=[]
    for key,title,status,text,paths in CLAIMS:
        artifacts=[]
        for rel in paths:
            p=ROOT/rel
            if not p.is_file():
                raise SystemExit(f"Missing claim artifact: {rel}")
            artifacts.append({"path":rel,"bytes":p.stat().st_size,"sha256":hashlib.sha256(p.read_bytes()).hexdigest()})
        claims.append({"id":key,"title":title,"evidence_class":status,"claim_and_limit":text,"artifacts":artifacts})
    j={"schema":"agi-alpha-strategy-evidence-docket/v1","source_hash":"7e5a1dd2dcf7eb00ec055f1858d5dd722cc950f15f33314bb94c456c753845a7","prospective_freeze_sha256":"6d0308707f3909fd18d086a950d237835dafd9ab6cfa9a559846715f46613827","claims":claims,"interpretation":"Integrity bindings do not supply independent institutional endorsement. Read the scope limits with each claim. The full package also retains exact raw inputs, unsuccessful candidates and outputs beyond these entry points."}
    (ROOT/'EVIDENCE_DOCKET.json').write_text(json.dumps(j,indent=2)+'\n')
    lines=['# Evidence docket','', 'Strategy as a Productive Asset — distinct Research & Engineering Edition 03.','',j['interpretation'],'']
    for c in claims:
        lines += [f"## {c['id']} · {c['title']}",'',f"**Evidence class:** {c['evidence_class']}",'',c['claim_and_limit'],'', '| Artifact | SHA-256 |','|---|---|']
        lines += [f"| `{a['path']}` | `{a['sha256']}` |" for a in c['artifacts']]
        lines += ['']
    (ROOT/'EVIDENCE_DOCKET.md').write_text('\n'.join(lines))
    print(json.dumps({'claims':len(claims),'bound_artifact_references':sum(len(c['artifacts']) for c in claims)}))

if __name__=='__main__': main()
